const DEFAULT_WARMUP_CAPACITY_CANDLES = 500;
const RECOVERY_RUNTIME_VERSION = "RECOVERY_SYNTHETIC_V1";
const RECOVERY_RUNTIME_SHA256 = createHash("sha256").update(RECOVERY_RUNTIME_VERSION, "utf8").digest("hex");
const value = <T>(input: T | string): T => typeof input === "string" ? JSON.parse(input) as T : input;
const date = (input: Date | string): string => new Date(input).toISOString();
const number = (input: number | string): number => typeof input === "number" ? input : Number(input);
const positiveNullable = (input: number | string | null | undefined): number | null => {
  if (input === null || input === undefined) return null;
  const parsed = number(input);
  if (!Number.isFinite(parsed) || parsed <= 0) throw new Error("BACKTEST_INVALID_TRADE_RISK_FIELD");
  return parsed;
};
const validateTradeRisk = (trade: Pick<Trade, "stopLoss" | "takeProfit">): void => {
  positiveNullable(trade.stopLoss);
  positiveNullable(trade.takeProfit);
};

const invalidSnapshot = (): never => { throw new Error("BACKTEST_INPUT_SNAPSHOT_INTEGRITY_FAILURE"); };
const validateInputSnapshot = (input: DatasetSnapshotRef, candles: Candle[]): void => {
  const interval = TIMEFRAME_SECONDS[input.timeframe] * 1_000;
  const from = Date.parse(input.range.from);
  const to = Date.parse(input.range.to);
  if (!input.id || !Number.isFinite(from) || !Number.isFinite(to) || to <= from || !Number.isInteger(input.candleCount) || input.candleCount <= 0 || input.candleCount !== candles.length || !/^[a-f0-9]{64}$/i.test(input.sha256)) invalidSnapshot();
  if (candles.some((item, index) => !item.isClosed || item.pair !== input.pair || item.timeframe !== input.timeframe || !Number.isFinite(Date.parse(item.timestamp)) || (index > 0 && Date.parse(item.timestamp) <= Date.parse(candles[index - 1]!.timestamp))) || new Set(candles.map((item) => item.timestamp)).size !== candles.length) invalidSnapshot();
  if (candles[0]!.timestamp !== input.range.from || candles.at(-1)!.timestamp !== new Date(to - interval).toISOString() || missingRanges(candles, input.range, input.timeframe).length > 0) invalidSnapshot();
  const expectedHash = createHash("sha256").update(snapshotSerialization(input.pair, input.timeframe, input.range, candles), "utf8").digest("hex");
  if (expectedHash !== input.sha256) invalidSnapshot();
};

interface SnapshotRow { id: string; pair: string; pair_metadata: DatasetSnapshotRef["pairMetadata"] | string; timeframe: DatasetSnapshotRef["timeframe"]; dataset_from: Date | string; dataset_to: Date | string; candle_count: number; sha256: string; created_at: Date | string; }
