      const current = await client.query<{ status: StoredCandidate["status"] }>("SELECT status FROM backtest_candidates WHERE id = $1 AND active_fence_token = $2 FOR UPDATE", [input.candidate.candidateId, input.fenceToken]);
      if (!current.rows[0]) throw new Error("BACKTEST_FENCE_LOST");
