      const attemptUpdate = await client.query<{ id: string }>("UPDATE backtest_attempts SET status = 'COMPLETED', trade_count = $3, audit_only = $4, lease_expires_at = NULL, completed_at = $5 WHERE id = $1 AND fence_token = $2 AND status = 'RUNNING' RETURNING id", [input.attempt.attemptId, input.fenceToken, input.result.trades.length, auditOnly, input.result.completedAt]);
      if (!attemptUpdate.rows[0]) throw new Error("BACKTEST_FENCE_LOST");
      for (const item of input.result.trades) await this.saveTrade(client, item);
      const candidateUpdate = await client.query<{ id: string }>("UPDATE backtest_candidates SET status = CASE WHEN status = 'CANCELLED' THEN 'CANCELLED' ELSE 'PROCESSING_RESULT' END, active_attempt_number = NULL, active_fence_token = NULL, active_lease_expires_at = NULL, completion_next_retry_at = CASE WHEN status = 'CANCELLED' THEN NULL ELSE $3::timestamptz END, updated_at = $3::timestamptz WHERE id = $1 AND active_fence_token = $2 AND status IN ('BACKTESTING', 'CANCELLED') RETURNING id", [input.candidate.candidateId, input.fenceToken, input.result.completedAt]);
